WITH subq1 AS ( WITH inner_cte AS ( SELECT ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC, EXP(AVG(LN(LIBRARY_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS))) AS geometric_mean_enrollment FROM ACADEMIC_TERMS_ALL JOIN LIBRARY_SUBJECT_OFFERED ON ACADEMIC_TERMS_ALL.TERM_CODE = LIBRARY_SUBJECT_OFFERED.TERM_CODE WHERE LIBRARY_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS > 0 GROUP BY ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC ) SELECT inner_cte.ACADEMIC_YEAR, inner_cte.ACADEMIC_YEAR_DESC, inner_cte.geometric_mean_enrollment, COUNT(DISTINCT LIBRARY_SUBJECT_OFFERED.OFFER_DEPT_CODE) AS num_departments FROM inner_cte JOIN ACADEMIC_TERMS_ALL ON inner_cte.ACADEMIC_YEAR = ACADEMIC_TERMS_ALL.ACADEMIC_YEAR JOIN LIBRARY_SUBJECT_OFFERED ON ACADEMIC_TERMS_ALL.TERM_CODE = LIBRARY_SUBJECT_OFFERED.TERM_CODE AND LIBRARY_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS > 0 GROUP BY inner_cte.ACADEMIC_YEAR, inner_cte.ACADEMIC_YEAR_DESC, inner_cte.geometric_mean_enrollment ), subq2 AS ( WITH inner_cte AS ( SELECT ata.ACADEMIC_YEAR_DESC, MAX(term_subject_count) - MIN(term_subject_count) AS subject_count_range, VARIANCE(term_subject_count) AS subject_count_variance, STDDEV(term_subject_count) AS subject_count_stddev FROM ACADEMIC_TERMS_ALL ata JOIN ACADEMIC_TERMS at ON ata.TERM_CODE = at.TERM_CODE JOIN ( SELECT tso.TERM_CODE, COUNT(*) AS term_subject_count FROM TIP_SUBJECT_OFFERED tso GROUP BY tso.TERM_CODE HAVING COUNT(*) > 0 ) tsc ON at.TERM_CODE = tsc.TERM_CODE GROUP BY ata.ACADEMIC_YEAR_DESC ) SELECT ic.ACADEMIC_YEAR_DESC, ic.subject_count_range, ic.subject_count_variance, ic.subject_count_stddev, CASE WHEN ic.subject_count_stddev > avg_stats.avg_stddev * 1.2 THEN 'HIGH_VARIABILITY' WHEN ic.subject_count_stddev < avg_stats.avg_stddev * 0.8 THEN 'LOW_VARIABILITY' ELSE 'AVERAGE' END AS variability_category FROM inner_cte ic CROSS JOIN ( SELECT AVG(subject_count_stddev) AS avg_stddev FROM inner_cte ) avg_stats ) SELECT subq1.ACADEMIC_YEAR, subq1.ACADEMIC_YEAR_DESC, subq1.geometric_mean_enrollment, subq1.num_departments, subq2.subject_count_range, subq2.subject_count_variance, subq2.subject_count_stddev, subq2.variability_category FROM subq1 JOIN subq2 ON subq1.ACADEMIC_YEAR_DESC = subq2.ACADEMIC_YEAR_DESC ORDER BY subq1.geometric_mean_enrollment DESC;